        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: MyApp
steps:
  test:
    command: jest
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

