//! Bivvy CLI entry point.

use std::process::ExitCode;

use bivvy::cli::{Cli, CommandDispatcher, Commands};
use bivvy::shell::is_ci;
use bivvy::ui::{create_ui, OutputMode};
use bivvy::updates::{
    apply_staged_update, is_notification_suppressed, perform_background_update,
    should_spawn_background_update, show_update_notification, spawn_background_update,
};
use clap::Parser;
use tracing_subscriber::{fmt, prelude::*, EnvFilter};

/// Initialize the tracing subscriber for logging.
///
/// Log level is controlled by:
/// 1. `--debug` flag sets level to DEBUG
/// 2. `RUST_LOG` environment variable (if set)
/// 3. Default is INFO
fn init_tracing(debug: bool) {
    let filter = if debug {
        EnvFilter::new("bivvy=debug")
    } else {
        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
    };

    tracing_subscriber::registry()
        .with(fmt::layer().with_target(false))
        .with(filter)
        .init();
}

fn main() -> ExitCode {
    // Safety net: claim the foreground process group for terminal I/O.
    //
    // When `cargo run` (or other launchers) spawn bivvy, the child may
    // not be the terminal's foreground process group. We ignore SIGTTOU
    // (so tcsetpgrp doesn't suspend us) and claim the foreground.
    //
    // The primary defense against SIGTTOU is using `-lc` (not `-lic`)
    // for child shell commands — see shell/command.rs. Without `-i`,
    // child shells don't set up job control and don't steal the
    // foreground group. These signal ignores and tcsetpgrp call are a
    // safety net for edge cases (e.g., `cargo run` wrappers).
    #[cfg(unix)]
    unsafe {
        libc::signal(libc::SIGTTOU, libc::SIG_IGN);
        libc::signal(libc::SIGTTIN, libc::SIG_IGN);

        let tty_fd = libc::open(c"/dev/tty".as_ptr(), libc::O_RDWR);
        if tty_fd >= 0 {
            libc::tcsetpgrp(tty_fd, libc::getpgrp());
            libc::close(tty_fd);
        }
    }

    // Background self-update process: when invoked with this env var,
    // perform the update check/download and exit immediately.
    if std::env::var("BIVVY_SELF_UPDATE_BG").is_ok() {
        let _ = perform_background_update();
        return ExitCode::SUCCESS;
    }

    let cli = Cli::parse();
    init_tracing(cli.debug);

    // Ensure ~/.bivvy/config.yml exists (first-run bootstrap).
    bivvy::config::ensure_global_config();

    tracing::debug!("Bivvy starting with args: {:?}", cli);

    // Determine output mode
    let output_mode = if cli.quiet {
        OutputMode::Quiet
    } else if cli.verbose {
        OutputMode::Verbose
    } else {
        OutputMode::Normal
    };

    // Handle --no-color
    if cli.no_color {
        std::env::set_var("NO_COLOR", "1");
    }

    // Determine project root
    let project_root = cli
        .project
        .as_ref()
        .cloned()
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());

    // Check if non-interactive (CI mode or explicit flag)
    let is_interactive = match &cli.command {
        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
        _ => !is_ci(),
    };

    // Create UI
    let mut ui = create_ui(is_interactive, output_mode);

    // Apply any previously staged update (manual installs only).
    // This replaces the current binary before running the command,
    // so the user gets the new version immediately.
    match apply_staged_update() {
        Ok(Some(version)) => {
            tracing::info!("Auto-updated to v{}", version);
            ui.message(&format!("bivvy has been auto-updated to v{}", version));
        }
        Ok(None) => {} // No staged update
        Err(e) => {
            tracing::warn!("Failed to apply staged update: {}", e);
        }
    }

    // Dispatch command
    let dispatcher = CommandDispatcher::new(project_root);

    let exit_code = match dispatcher.dispatch(&cli, ui.as_mut()) {
        Ok(result) => {
            // Show update notification after successful runs
            if result.success && is_interactive && !is_notification_suppressed() {
                show_update_notification(ui.as_mut());
            }
            result.exit_code as u8
        }
        Err(e) => {
            ui.error(&format!("Error: {}", e));
            1
        }
    };

    // Spawn background update check after command completes.
    // This runs in a detached process so it doesn't delay the CLI exit.
    if should_spawn_background_update(is_interactive, is_ci()) {
        if let Err(e) = spawn_background_update() {
            tracing::debug!("Failed to spawn background update: {}", e);
        }
    }

    ExitCode::from(exit_code)
}

//! Configuration schema definitions for Bivvy.
//!
//! This module contains all the struct definitions that map to
//! the YAML configuration file format.

use crate::checks::{Check, SatisfactionCondition};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Helper for `serde_yaml::Value` fields — accepts any valid YAML/JSON value.
fn any_value_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    true.into()
}

/// Helper for `HashMap<String, serde_yaml::Value>` — object with any values.
fn any_value_map_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    let mut map = serde_json::Map::new();
    map.insert(
        "type".to_string(),
        serde_json::Value::String("object".to_string()),
    );
    map.insert(
        "additionalProperties".to_string(),
        serde_json::Value::Bool(true),
    );
    map.into()
}

/// Root configuration structure for bivvy.yml
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct BivvyConfig {
    /// Application name (for display purposes)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub app_name: Option<String>,

    /// Global settings
    pub settings: Settings,

    /// Remote template sources
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub template_sources: Vec<TemplateSource>,

    /// Step definitions
    #[serde(default)]
    pub steps: HashMap<String, StepConfig>,

    /// Workflow definitions
    #[serde(default)]
    pub workflows: HashMap<String, WorkflowConfig>,

    /// Secrets configuration
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub secrets: HashMap<String, SecretConfig>,

    /// Config inheritance
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extends: Option<Vec<ExtendsConfig>>,

    /// Custom requirement definitions
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub requirements: HashMap<String, CustomRequirement>,

    /// User-defined variables for interpolation.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,
}

/// JSONL event logging settings.
///
/// Controls whether structured event logs are written to `~/.bivvy/logs/`
/// and how long they are retained.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct LoggingSettings {
    /// Enable JSONL event logging. When false, no log files are written.
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub logging: bool,

    /// Maximum age of log files in days. Files older than this are deleted
    /// during cleanup. Default: 30.
    #[serde(
        default = "default_log_retention_days",
        skip_serializing_if = "is_default_log_retention_days"
    )]
    pub log_retention_days: u32,

    /// Maximum total size of log files in megabytes. When exceeded, oldest
    /// files are deleted first. Default: 500.
    #[serde(
        default = "default_log_retention_mb",
        skip_serializing_if = "is_default_log_retention_mb"
    )]
    pub log_retention_mb: u64,
}

impl Default for LoggingSettings {
    fn default() -> Self {
        Self {
            logging: true,
            log_retention_days: default_log_retention_days(),
            log_retention_mb: default_log_retention_mb(),
        }
    }
}

impl LoggingSettings {
    /// Convert to a [`RetentionPolicy`](crate::logging::RetentionPolicy).
    pub fn to_retention_policy(&self) -> crate::logging::RetentionPolicy {
        crate::logging::RetentionPolicy {
            max_age_days: self.log_retention_days,
            max_size_mb: self.log_retention_mb,
        }
    }
}

fn default_log_retention_days() -> u32 {
    30
}

fn is_default_log_retention_days(v: &u32) -> bool {
    *v == default_log_retention_days()
}

fn default_log_retention_mb() -> u64 {
    500
}

fn is_default_log_retention_mb(v: &u64) -> bool {
    *v == default_log_retention_mb()
}

/// Execution-related settings (parallelism, history, updates).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct ExecutionSettings {
    /// Enable parallel execution
    #[serde(default, skip_serializing_if = "is_false")]
    pub parallel: bool,

    /// Maximum concurrent steps
    #[serde(
        default = "default_max_parallel",
        skip_serializing_if = "is_default_max_parallel"
    )]
    pub max_parallel: usize,

    /// History retention count

