        let workflows_dir = temp.path().join(".bivvy").join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();
        let path = workflows_dir.join("release.yml");
        fs::write(
            &path,
            r#"
description: "Release prep"
steps:
  fetch:
    command: "git fetch"
vars:
  ver: "1.0"
workflow:
  steps:
    - fetch
"#,
        )
        .unwrap();

        let file = load_single_workflow_file(&path).unwrap();
        assert_eq!(file.description, Some("Release prep".to_string()));
        assert!(file.steps.contains_key("fetch"));
        assert!(file.vars.contains_key("ver"));
        assert_eq!(file.workflow.steps, vec!["fetch"]);
    }

    #[test]
    fn load_single_step_file_parses_step_yaml() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("step.yml");
        fs::write(
            &path,
            r#"
title: "Setup database"
command: "rails db:setup"
"#,
        )
        .unwrap();

        let step = load_single_step_file(&path).unwrap();
        assert_eq!(step.title, Some("Setup database".to_string()));
        assert_eq!(step.execution.command, Some("rails db:setup".to_string()));
    }

    #[test]
    fn load_for_run_only_loads_named_workflow_file() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Test").unwrap();

        // The workflow we want to run.
        fs::write(
            workflows_dir.join("good.yml"),
            r#"
description: "Good workflow"
steps:
  hello:
    command: "echo hello"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        // A malformed sibling — must not be parsed.
        fs::write(
            workflows_dir.join("broken.yml"),
            "this: is: not: valid: yaml: at all",
        )
        .unwrap();

        let config = load_for_run(temp.path(), "good").unwrap();
        assert!(config.workflows.contains_key("good"));
        assert!(!config.workflows.contains_key("broken"));
        assert!(config.steps.contains_key("hello"));
    }

    #[test]
    fn load_for_run_workflow_step_overrides_project_step() {
        // Resolution chain: project (3) → workflow file (5) → local (6).
        // Workflow files override project config; local overrides everything.
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(
            bivvy.join("config.yml"),
            r#"
app_name: Test
steps:
  hello:
    command: "from project"
"#,
        )
        .unwrap();

        fs::write(
            workflows_dir.join("greet.yml"),
            r#"
steps:
  hello:
    command: "from workflow file"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "greet").unwrap();
        assert_eq!(
            config.steps["hello"].execution.command,
            Some("from workflow file".to_string())
        );
    }

    #[test]
    fn load_for_run_local_overrides_workflow_step() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Test").unwrap();

        fs::write(
            workflows_dir.join("greet.yml"),
            r#"
steps:
  hello:
    command: "workflow"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        fs::write(
            bivvy.join("config.local.yml"),
            r#"
steps:
  hello:
    command: "local override"
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "greet").unwrap();
        assert_eq!(
            config.steps["hello"].execution.command,
            Some("local override".to_string())
        );
    }

    #[test]
    fn load_for_run_handles_legacy_workflow_layout() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(
            bivvy.join("config.yml"),
            r#"
app_name: Legacy
steps:
  deps:
    command: "yarn install"
"#,
        )
        .unwrap();

        fs::write(
            workflows_dir.join("ci.yml"),
            r#"
description: "Legacy CI"
steps: [deps]
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "ci").unwrap();
        let workflow = config.workflows.get("ci").unwrap();
        assert_eq!(workflow.description, Some("Legacy CI".to_string()));
        assert_eq!(workflow.steps, vec!["deps"]);
        assert!(config.steps.contains_key("deps"));
    }

    #[test]
    fn load_config_value_rejects_non_mapping_yaml() {
        let temp = TempDir::new().unwrap();

        // Scalar value
        let path = temp.path().join("scalar.yml");
        fs::write(&path, "just a string").unwrap();
        let result = load_config_value(&path);
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "scalar YAML should be rejected, got: {:?}",
            result
        );

        // Sequence value
        let path = temp.path().join("list.yml");
        fs::write(&path, "- item1\n- item2\n").unwrap();
        let result = load_config_value(&path);
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "sequence YAML should be rejected, got: {:?}",
            result
        );
    }

    #[test]
    fn load_config_value_converts_empty_file_to_empty_mapping() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("empty.yml");
        fs::write(&path, "").unwrap();

        let value = load_config_value(&path).unwrap();
        assert!(
            value.is_mapping(),
            "empty file should produce an empty mapping, got: {:?}",
            value
        );
        assert!(value.as_mapping().unwrap().is_empty());
    }

    #[test]
    fn load_config_value_rejects_non_trivial_content_parsing_as_null() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("null.yml");
        // A YAML document with content that resolves to null
        fs::write(&path, "--- null\n").unwrap();
        let result = load_config_value(&path);
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "non-trivial content parsing as null should be rejected, got: {:?}",
            result
        );
    }

    #[test]
    fn parse_config_rejects_non_mapping_content() {
        // Scalar
        let result = parse_config("just a string", Path::new("test.yml"));
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "scalar content should be rejected, got: {:?}",
            result
        );

        // Sequence
        let result = parse_config("- a\n- b\n", Path::new("test.yml"));
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "sequence content should be rejected, got: {:?}",
            result
        );
    }

    #[test]
    fn load_merged_config_does_not_silently_default_on_invalid_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Write a config that is valid YAML but not a mapping
        fs::write(bivvy_dir.join("config.yml"), "- step1\n- step2\n").unwrap();

        let result = load_merged_config(temp.path());
        assert!(
            result.is_err(),
            "non-mapping project config should error, not silently default"
        );
    }

    #[test]
    fn null_overlay_does_not_wipe_base_config_during_merge() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Project config with real content
        fs::write(
            bivvy_dir.join("config.yml"),
            "app_name: TestApp\nsteps:\n  hello:\n    command: echo hello\n",
        )
        .unwrap();

        // Local override that is an empty file (would parse as null)
        fs::write(bivvy_dir.join("config.local.yml"), "").unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(
            config.app_name,
            Some("TestApp".to_string()),
            "empty local override should not wipe project config"
        );
        assert!(
            config.steps.contains_key("hello"),
            "empty local override should not wipe project steps"
        );
    }

    #[test]
    fn load_merged_config_handles_new_format_workflow_files() {
        let temp = TempDir::new().unwrap();
        let bivvy = temp.path().join(".bivvy");
        let workflows_dir = bivvy.join("workflows");
        fs::create_dir_all(&workflows_dir).unwrap();

        fs::write(bivvy.join("config.yml"), "app_name: Mixed").unwrap();

        fs::write(
            workflows_dir.join("release.yml"),
            r#"
description: "Release"
steps:
  fetch:
    command: "git fetch"
workflow:
  steps:
    - fetch
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        let workflow = config.workflows.get("release").unwrap();
        assert_eq!(workflow.description, Some("Release".to_string()));
        assert_eq!(workflow.steps, vec!["fetch"]);
        assert!(config.steps.contains_key("fetch"));
    }
}

