        // step and outcome_kind() returns None.
        let temp = TempDir::new().unwrap();
        let log_file = temp.path().join("unknown.jsonl");
        let event = serde_json::json!({
            "ts": "2026-04-25T10:00:01.000Z",
            "session": "sess_test",
