    #[test]
    fn outcome_status_kind_matches_run_ui() {
        // bivvy run uses these StatusKind glyphs for each outcome — bivvy
        // last must match.
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::Completed),
            StatusKind::Success
        );
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::Failed),
            StatusKind::Failed
        );
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::Satisfied),
            StatusKind::Success
        );
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::Declined),
            StatusKind::Skipped
        );
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::FilteredOut),
            StatusKind::Skipped
        );
        assert_eq!(
            outcome_status_kind(StepOutcomeKind::Blocked),
            StatusKind::Blocked
        );
    }

    /// Helper: write a `session_started` + `workflow_completed` log file for `project`.
    fn write_run_log(log_dir: &Path, name: &str, project: &Path, workflow: &str, success: bool) {
        let session_started = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_test",
            "type": "session_started",
            "command": "run",
            "args": [workflow],
            "version": "1.10.0",
            "working_directory": project.display().to_string()
        });
        let wc = serde_json::json!({
            "ts": "2026-04-25T10:00:02.000Z",
            "session": "sess_test",
            "type": "workflow_completed",
            "name": workflow,
            "success": success,
            "aborted": false,
            "steps_run": 1,
            "steps_skipped": 0,
            "duration_ms": 1000
        });
        std::fs::write(log_dir.join(name), format!("{}\n{}\n", session_started, wc)).unwrap();
    }

    /// Helper: write a status-style log (session_started only, no workflow_completed).
    fn write_status_log(log_dir: &Path, name: &str, project: &Path) {
        let session = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_test",
            "type": "session_started",
            "command": "status",
            "args": [],
            "version": "1.10.0",
            "working_directory": project.display().to_string()
        });
        std::fs::write(log_dir.join(name), format!("{}\n", session)).unwrap();
    }

    #[test]
    fn scan_log_dir_skips_logs_without_workflow_completed() {
        // Reproduces the bug: when the most recent log (by filename) is from
        // a non-`run` command like `bivvy status`, `bivvy last` should still
        // surface the most recent actual run rather than reporting "no runs".
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-03_aaaaaaaa.jsonl",
            &canonical,
            "default",
            true,
        );
        write_status_log(
            log_dir.path(),
            "2026-04-28T22-26-03_status.jsonl",
            &canonical,
        );

        let runs = scan_log_dir(log_dir.path(), false, &canonical);
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].workflow, "default");
        assert!(runs[0].success);
    }

    #[test]
    fn scan_log_dir_filters_other_projects() {
        let project_a = TempDir::new().unwrap();
        let project_b = TempDir::new().unwrap();
        let canonical_a = project_a.path().canonicalize().unwrap();
        let canonical_b = project_b.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-03_aaaa.jsonl",
            &canonical_a,
            "default",
            true,
        );
        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-04_bbbb.jsonl",
            &canonical_b,
            "default",
            true,
        );

        let runs_a = scan_log_dir(log_dir.path(), true, &canonical_a);
        assert_eq!(runs_a.len(), 1);

        let runs_b = scan_log_dir(log_dir.path(), true, &canonical_b);
        assert_eq!(runs_b.len(), 1);
    }

    #[test]
    fn scan_log_dir_returns_empty_when_no_logs_match_project() {
        let project = TempDir::new().unwrap();
        let other = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let canonical_other = other.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-03_aaaa.jsonl",
            &canonical_other,
            "default",
            true,
        );

        let runs = scan_log_dir(log_dir.path(), false, &canonical);
        assert!(runs.is_empty());
    }

    #[test]
    fn scan_log_dir_with_all_returns_runs_newest_first() {
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-01_aaaa.jsonl",
            &canonical,
            "first",
            true,
        );
        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-05_bbbb.jsonl",
            &canonical,
            "second",
            true,
        );

        let runs = scan_log_dir(log_dir.path(), true, &canonical);
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0].workflow, "second");
        assert_eq!(runs[1].workflow, "first");
    }
}

//! Automatic fix application.
//!
//! This module provides functionality for automatically fixing
//! configuration issues detected by lint rules.

use crate::lint::LintDiagnostic;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// A code fix that can be applied automatically.
#[derive(Debug, Clone)]
pub struct Fix {
    /// File to modify.
    pub file: PathBuf,
    /// Start byte offset.
    pub start: usize,
    /// End byte offset.
    pub end: usize,
    /// Replacement text.
    pub replacement: String,
}

/// Result of attempting to apply fixes.
#[derive(Debug)]
pub struct FixResult {
    /// Number of fixes applied.
    pub applied: usize,
    /// Diagnostics that couldn't be auto-fixed.
    pub unfixable: Vec<LintDiagnostic>,
    /// Errors that occurred during fixing.
    pub errors: Vec<String>,
}

/// Engine for applying automatic fixes.
pub struct FixEngine;

impl FixEngine {
    /// Create a new fix engine.
    pub fn new() -> Self {
        Self
    }

    /// Apply fixes from diagnostics that support auto-fix.
    pub fn apply_fixes(&self, diagnostics: &[LintDiagnostic], fixes: &[Fix]) -> FixResult {
        let mut applied = 0;
        let mut errors = Vec::new();

        // Group fixes by file
        let mut fixes_by_file: HashMap<&Path, Vec<&Fix>> = HashMap::new();
        for fix in fixes {
            fixes_by_file
                .entry(fix.file.as_path())
                .or_default()
                .push(fix);
        }

        // Apply fixes to each file
        for (file, file_fixes) in fixes_by_file {
            match self.apply_fixes_to_file(file, &file_fixes) {
                Ok(count) => applied += count,
                Err(e) => errors.push(format!("{}: {}", file.display(), e)),
            }
        }

        // Collect unfixable diagnostics
        let unfixable = diagnostics
            .iter()
            .filter(|d| d.suggestion.is_none())
            .cloned()
            .collect();

        FixResult {
            applied,
            unfixable,
            errors,
        }
    }

    /// Preview fixes without applying them.
    pub fn preview_fixes(&self, fixes: &[Fix]) -> Vec<String> {
        fixes
            .iter()
            .map(|f| {
                format!(
                    "{}:{}-{}: Replace with '{}'",
                    f.file.display(),
                    f.start,
                    f.end,
                    f.replacement
                )
            })
            .collect()
    }

    fn apply_fixes_to_file(&self, file: &Path, fixes: &[&Fix]) -> Result<usize, String> {
        let content =
            fs::read_to_string(file).map_err(|e| format!("Failed to read file: {}", e))?;

        // Sort fixes by start position (reverse order for safe replacement)
        let mut sorted_fixes = fixes.to_vec();
        sorted_fixes.sort_by(|a, b| b.start.cmp(&a.start));

        let mut new_content = content;
        for fix in &sorted_fixes {
            if fix.start <= new_content.len() && fix.end <= new_content.len() {
                new_content = format!(
                    "{}{}{}",
                    &new_content[..fix.start],
                    &fix.replacement,
                    &new_content[fix.end..]
                );
            }
        }

        fs::write(file, new_content).map_err(|e| format!("Failed to write file: {}", e))?;

        Ok(sorted_fixes.len())
    }
}

impl Default for FixEngine {
    fn default() -> Self {
        Self::new()
    }
}

