//! Two context sources:
//! 1. **Step context** — command, requires, template (already available)
//! 2. **Workflow state** — prior step results, what succeeded/failed/was skipped

use crate::steps::StepStatus;

use super::classify::ErrorCategory;
use super::{CategoryMatch, DiagnosticDetails, StepContext, WorkflowState};

/// Refine category confidence and details using step + workflow context.
pub fn contextualize(
    categories: &mut [CategoryMatch],
    details: &mut DiagnosticDetails,
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) {
    for cat in categories.iter_mut() {
        // Step context reinforcement
        apply_step_context_boost(cat, details, step_ctx);

        // Workflow state heuristics
        apply_workflow_heuristics(cat, details, step_ctx, workflow_state);

        // Clamp confidence to [0.0, 1.0]
        cat.confidence = cat.confidence.clamp(0.0, 1.0);
    }

    // Re-sort by confidence after adjustments
    categories.sort_by(|a, b| {
        b.confidence
            .partial_cmp(&a.confidence)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    // Extract service name from requires if we have a connection_refused
    if categories
        .iter()
        .any(|c| c.category == ErrorCategory::ConnectionRefused)
        && details.service.is_none()
    {
        for req in step_ctx.requires {
            if req.contains("postgres")
                || req.contains("redis")
                || req.contains("mysql")
                || req.contains("mongo")
                || req.contains("elasticsearch")
                || req.contains("rabbitmq")
                || req.contains("memcached")
            {
                details.service = Some(req.clone());
                break;
            }
        }
    }
}

fn apply_step_context_boost(
    cat: &mut CategoryMatch,
    details: &DiagnosticDetails,
    step_ctx: &StepContext<'_>,
) {
    match cat.category {
        ErrorCategory::ConnectionRefused
            if step_ctx.requires.iter().any(|r| {
                r.contains("postgres")
                    || r.contains("redis")
                    || r.contains("mysql")
                    || r.contains("mongo")
                    || r.contains("server")
            }) =>
        {
            cat.confidence += 0.15;
        }
        ErrorCategory::NotFound if is_install_command(step_ctx.command) => {
            cat.confidence += 0.15;
        }
        ErrorCategory::VersionMismatch
            if details.version_have.is_some() && details.version_need.is_some() =>
        {
            cat.confidence += 0.15;
        }
        ErrorCategory::SyncIssue if is_package_manager_command(step_ctx.command) => {
            cat.confidence += 0.15;
        }
        ErrorCategory::SystemConstraint
            if step_ctx.command.contains("pip") || step_ctx.command.contains("python") =>
        {
            cat.confidence += 0.15;
        }
        ErrorCategory::AuthFailure
            if step_ctx.command.contains("git") || step_ctx.command.contains("ssh") =>
        {
            cat.confidence += 0.15;
        }
        _ => {}
    }
}

fn apply_workflow_heuristics(
    cat: &mut CategoryMatch,
    _details: &DiagnosticDetails,
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) {
    match cat.category {
        ErrorCategory::ConnectionRefused => {
            // If a service-start step already succeeded, the service may have crashed
            if has_service_step_succeeded(step_ctx, workflow_state) {
                cat.confidence += 0.1;
            }
        }
        ErrorCategory::NotFound => {
            // If an install step for same ecosystem already succeeded,
            // the issue is likely a wrong package name, not a missing install
            if has_install_step_succeeded(step_ctx, workflow_state) {
                cat.confidence += 0.1;
            }
        }
        _ => {}
    }
}

/// Check if a step that starts a service required by the current step
/// has already succeeded.
pub(super) fn has_service_step_succeeded(
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) -> bool {
    for (name, step) in workflow_state.steps {
        if *name == step_ctx.name {
            continue;
        }
        let is_service_step = step.execution.command.contains("start")
            || step.execution.command.split_whitespace().any(|w| w == "up");
        if is_service_step {
            if let Some(status) = workflow_state.outcomes.get(*name) {
                if *status == StepStatus::Completed {
                    return true;
                }
            }
        }
    }
    false
}

/// Check if an install/dependency step for a similar ecosystem already succeeded.
pub(super) fn has_install_step_succeeded(
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) -> bool {
    let ecosystem = detect_ecosystem(step_ctx.command);
    if ecosystem.is_empty() {
        return false;
    }

    for (name, step) in workflow_state.steps {
        if *name == step_ctx.name {
            continue;
        }
        if is_install_command(&step.execution.command)
            && detect_ecosystem(&step.execution.command) == ecosystem
        {
            if let Some(status) = workflow_state.outcomes.get(*name) {
                if *status == StepStatus::Completed {
                    return true;
                }
            }
        }
    }
    false
}

/// Check if a step that installs dependencies for the same ecosystem was skipped.
pub(super) fn was_install_step_skipped(
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) -> Option<String> {
    let ecosystem = detect_ecosystem(step_ctx.command);
    if ecosystem.is_empty() {
        return None;
    }

    for (name, step) in workflow_state.steps {
        if *name == step_ctx.name {
            continue;
        }
        if is_install_command(&step.execution.command)
            && detect_ecosystem(&step.execution.command) == ecosystem
        {
            if let Some(status) = workflow_state.outcomes.get(*name) {
                if *status == StepStatus::Skipped {
                    return Some((*name).to_string());
                }
            }
        }
    }
    None
}

/// Check if any install step exists for the same ecosystem.
pub(super) fn has_install_step(
    step_ctx: &StepContext<'_>,
    workflow_state: &WorkflowState<'_>,
) -> bool {
    let ecosystem = detect_ecosystem(step_ctx.command);
    if ecosystem.is_empty() {
        return false;
    }

    workflow_state.steps.iter().any(|(name, step)| {
        *name != step_ctx.name
            && is_install_command(&step.execution.command)
            && detect_ecosystem(&step.execution.command) == ecosystem
    })
}

fn is_install_command(cmd: &str) -> bool {
    cmd.contains("install")
        || cmd.contains("bundle")
        || cmd.contains("pip")
        || cmd.contains("yarn")
        || cmd.contains("npm i")
        || cmd.contains("composer")
        || cmd.contains("cargo build")
        || cmd.contains("mix deps")
        || cmd.contains("go mod")
        || cmd.contains("dotnet restore")
        || cmd.contains("mvn install")
}

fn is_package_manager_command(cmd: &str) -> bool {
    cmd.contains("bundle")
        || cmd.contains("npm")
        || cmd.contains("yarn")
        || cmd.contains("pip")
        || cmd.contains("poetry")
        || cmd.contains("cargo")
        || cmd.contains("mix")
        || cmd.contains("go mod")
        || cmd.contains("composer")
        || cmd.contains("maven")
        || cmd.contains("gradle")
        || cmd.contains("dotnet")
}

fn detect_ecosystem(cmd: &str) -> &str {
    if cmd.contains("bundle") || cmd.contains("gem") || cmd.contains("ruby") {
        "ruby"
    } else if cmd.contains("npm")
        || cmd.contains("yarn")
        || cmd.contains("node")
        || cmd.contains("pnpm")
    {
        "node"
    } else if cmd.contains("pip")
        || cmd.contains("python")
        || cmd.contains("poetry")
        || cmd.contains("conda")
    {
        "python"
    } else if cmd.contains("cargo") || cmd.contains("rustc") {
        "rust"
    } else if cmd.contains("go ") || cmd.contains("go.") {
        "go"
    } else if cmd.contains("mix") || cmd.contains("elixir") {
        "elixir"
    } else if cmd.contains("mvn") || cmd.contains("gradle") || cmd.contains("java") {
        "java"
    } else if cmd.contains("dotnet") || cmd.contains("nuget") {
        "dotnet"
    } else if cmd.contains("docker") {
        "docker"
    } else if cmd.contains("composer") || cmd.contains("php") {
        "php"
    } else {
        ""
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn make_ctx<'a>(command: &'a str, requires: &'a [String]) -> StepContext<'a> {
        StepContext {
            name: "test",
            command,
            requires,
            template: None,
        }
    }

    #[test]
    fn connection_refused_boosted_by_requires() {
        let requires = vec!["postgres-server".to_string()];
        let ctx = make_ctx("rails db:create", &requires);
        let outcomes = HashMap::new();
        let ws = WorkflowState {
            steps: &[],
            outcomes: &outcomes,
        };

        let mut cats = vec![CategoryMatch {
            category: ErrorCategory::ConnectionRefused,
            confidence: 0.3,
        }];
        let mut details = DiagnosticDetails::default();

        contextualize(&mut cats, &mut details, &ctx, &ws);

        assert!(cats[0].confidence > 0.3);
        assert_eq!(details.service.as_deref(), Some("postgres-server"));
    }

    #[test]
    fn not_found_boosted_by_install_command() {
        let ctx = make_ctx("pip install -r requirements.txt", &[]);
        let outcomes = HashMap::new();
        let ws = WorkflowState {
            steps: &[],
            outcomes: &outcomes,
        };

        let mut cats = vec![CategoryMatch {
            category: ErrorCategory::NotFound,
            confidence: 0.3,
        }];
        let mut details = DiagnosticDetails::default();

        contextualize(&mut cats, &mut details, &ctx, &ws);

        assert!(cats[0].confidence > 0.3);
    }

    #[test]
    fn system_constraint_boosted_by_pip() {
        let ctx = make_ctx("pip install flask", &[]);
        let outcomes = HashMap::new();
        let ws = WorkflowState {
            steps: &[],
            outcomes: &outcomes,
        };

        let mut cats = vec![CategoryMatch {
            category: ErrorCategory::SystemConstraint,
            confidence: 0.3,
        }];
        let mut details = DiagnosticDetails::default();

        contextualize(&mut cats, &mut details, &ctx, &ws);

        assert!(cats[0].confidence > 0.3);
    }

    #[test]
    fn ecosystem_detection() {
        assert_eq!(detect_ecosystem("bundle install"), "ruby");
        assert_eq!(detect_ecosystem("npm install"), "node");
        assert_eq!(detect_ecosystem("pip install flask"), "python");
        assert_eq!(detect_ecosystem("cargo build"), "rust");
        assert_eq!(detect_ecosystem("echo hello"), "");
    }

    #[test]
    fn confidence_clamped_to_1() {
        let ctx = make_ctx("pip install flask", &[]);
        let outcomes = HashMap::new();
        let ws = WorkflowState {
            steps: &[],
            outcomes: &outcomes,
        };

        let mut cats = vec![CategoryMatch {
            category: ErrorCategory::SystemConstraint,
            confidence: 0.95,
        }];
        let mut details = DiagnosticDetails::default();

        contextualize(&mut cats, &mut details, &ctx, &ws);

        assert!(cats[0].confidence <= 1.0);
    }

    #[test]
    fn resorts_after_boost() {
        let ctx = make_ctx("bundle install", &[]);
        let outcomes = HashMap::new();
        let ws = WorkflowState {
            steps: &[],
            outcomes: &outcomes,
        };

        let mut cats = vec![
            CategoryMatch {
                category: ErrorCategory::BuildFailure,
                confidence: 0.4,
            },
            CategoryMatch {
                category: ErrorCategory::NotFound,
                confidence: 0.3,
            },
        ];
        let mut details = DiagnosticDetails::default();

        contextualize(&mut cats, &mut details, &ctx, &ws);

        // NotFound gets boosted by install command, may reorder
        assert!(cats[0].confidence >= cats[1].confidence);
    }
}

//! Workflow-level display contract.
//!
//! Owns the run header, persistent progress bar (pinned at the bottom),
//! and the run summary. Delegates per-step rendering to
//! [`super::StepDisplay`].
//!
//! ## Construction
//!
//! - Interactive runs: [`TerminalWorkflowDisplay::new`] with an
//!   [`Arc<TerminalSurface>`] and [`OutputMode`].
//! - CI / non-interactive: [`NonInteractiveWorkflowDisplay::new`].

use std::sync::Arc;
use std::time::Duration;

use indicatif::{ProgressBar, ProgressStyle};

use crate::ui::progress::format_duration;
use crate::ui::surface::{PinnedBar, TerminalSurface};
use crate::ui::theme::BivvyTheme;
use crate::ui::OutputMode;

use super::step::{NonInteractiveStepDisplay, StepDisplay, TerminalStepDisplay};
use super::{RunHeader, RunSummary};

/// Workflow-level display contract.
///
/// Implementations own the workflow's pinned progress bar (if any) and
/// produce per-step displays via [`Self::begin_step`].
pub trait WorkflowDisplay {
    /// Show the rich run header at the top of a run.
    fn show_run_header(&mut self, hdr: &RunHeader);

    /// Initialize the persistent progress bar.
    ///
    /// Called once before the step loop. Implementations that don't
    /// support a pinned bar (CI mode, silent mode) make this a no-op.
    fn start_progress(&mut self, total: usize);

    /// Update the progress bar.
    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration);

    /// Finish and clear the progress bar before the summary is rendered.
    fn finish_progress(&mut self);

    /// Show a run summary at the end of a run.
    fn show_run_summary(&mut self, summary: &RunSummary);

    /// Hand off to the step layer.
    ///
    /// The returned [`StepDisplay`] shares only the surface (or output
    /// stream) with the workflow — never any draw state.
    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay>;

    /// Print a status line above the pinned region (used for filter
    /// reasons, dry-run notes, etc.).
    fn message(&mut self, msg: &str);

    /// Print a hint (post-run guidance) above the pinned region.
    fn hint(&mut self, hint: &str);
}

// ────────────────────────── Interactive impl ──────────────────────────

/// Interactive workflow display backed by a [`TerminalSurface`].
pub struct TerminalWorkflowDisplay {
    surface: Arc<TerminalSurface>,
    theme: BivvyTheme,
    mode: OutputMode,
    pinned: Option<PinnedBar>,
}

impl TerminalWorkflowDisplay {
    /// Construct a new terminal workflow display.
    pub fn new(surface: Arc<TerminalSurface>, mode: OutputMode) -> Self {
        let theme = if crate::ui::should_use_colors() {
            BivvyTheme::new()
        } else {
            BivvyTheme::plain()
        };
        Self {
            surface,
            theme,
            mode,
            pinned: None,
        }
    }

    /// Format the bar message string with bracket bar + counts.
    fn format_bar(theme: &BivvyTheme, current: usize, total: usize, elapsed: Duration) -> String {
        let filled = if total > 0 { (current * 16) / total } else { 0 };
        let empty = 16usize.saturating_sub(filled);
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
        format!(
            "\n{} {}/{} steps {} {}",
            theme.info.apply_to(format!("[{}]", bar)),
            current,
            total,
            theme.dim.apply_to("·"),
            theme
                .duration
                .apply_to(format!("{} elapsed", format_duration(elapsed))),
        )
    }
}

impl WorkflowDisplay for TerminalWorkflowDisplay {
    fn show_run_header(&mut self, hdr: &RunHeader) {
        if !self.mode.shows_status() {
            return;
        }
        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
        self.surface.println(&format!(
            "\n{} {} {} {} {} {} {}\n",
            self.theme.header.apply_to("⛺"),
            self.theme.highlight.apply_to(&hdr.app_name),
            self.theme.dim.apply_to(format!("v{}", hdr.version)),
            self.theme.dim.apply_to("·"),
            self.theme
                .dim
                .apply_to(format!("{} workflow", hdr.workflow)),
            self.theme
                .dim
                .apply_to(format!("· {} {}", hdr.step_count, step_label)),
            self.theme.dim.apply_to(format!("· env: {}", hdr.env_name)),
        ));
    }

    fn start_progress(&mut self, total: usize) {
        if !self.mode.shows_status() {
            return;
        }
        let bar = ProgressBar::new(total as u64);
        bar.set_style(ProgressStyle::default_bar().template("{msg}").unwrap());
        bar.set_message(Self::format_bar(&self.theme, 0, total, Duration::ZERO));
        self.pinned = Some(self.surface.pin_bottom(bar));
    }

    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
        if !self.mode.shows_status() {
            return;
        }
        if let Some(p) = &self.pinned {
            p.set_message(Self::format_bar(&self.theme, current, total, elapsed));
        }
    }

    fn finish_progress(&mut self) {
        // Drop clears the bar.
        self.pinned = None;
    }

    fn show_run_summary(&mut self, summary: &RunSummary) {
        if !self.mode.shows_status() {
            return;
        }

        let b = &self.theme.border;
        let mut lines = vec![
            String::new(),
            format!(
                "{} {}",
                b.apply_to("┌─"),
                b.apply_to("Summary ──────────────────────────")
            ),
        ];

        for step in &summary.step_results {
            let icon = step.status.styled(&self.theme);
            let duration_str = step.duration.map(format_duration).unwrap_or_default();
            let detail_str = step.detail.as_deref().unwrap_or("");

            let right_side = if !duration_str.is_empty() {
                self.theme.duration.apply_to(duration_str).to_string()
            } else if !detail_str.is_empty() {
                self.theme.dim.apply_to(detail_str).to_string()
            } else {
                String::new()
            };

            lines.push(format!(
                "{} {} {:<20} {}",
                b.apply_to("│"),
                icon,
                step.name,
                right_side,
            ));
        }

        let satisfied_part = if summary.steps_satisfied > 0 {
            format!(
                " {} {} already satisfied",
                self.theme.dim.apply_to("·"),
                summary.steps_satisfied,
            )
        } else {
            String::new()
        };
        lines.push(
            b.apply_to("├────────────────────────────────────")
                .to_string(),
        );
        lines.push(format!(
            "{} Total: {} {} {} run {} {} skipped{}",
            b.apply_to("│"),
            self.theme
                .duration
                .apply_to(format_duration(summary.total_duration)),
            self.theme.dim.apply_to("·"),
            summary.steps_run,
            self.theme.dim.apply_to("·"),
            summary.steps_skipped,
            satisfied_part,
        ));
        lines.push(
            b.apply_to("└────────────────────────────────────")
                .to_string(),
        );

        for line in &lines {
            self.surface.println(line);
        }
    }

    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
        Box::new(TerminalStepDisplay::new(
            Arc::clone(&self.surface),
            self.mode,
            index,
            total,
        ))
    }

    fn message(&mut self, msg: &str) {
        if self.mode.shows_status() {
            self.surface.println(msg);
        }
    }

    fn hint(&mut self, hint: &str) {
        if !self.mode.shows_status() {
            return;
        }
        self.surface
            .println(&self.theme.hint.apply_to(hint).to_string());
        self.surface.println("");
    }
}

// ─────────────────────── Non-interactive impl ────────────────────────

/// Non-interactive (CI / headless) workflow display.
///
/// Prints structured lines to stdout/stderr; skips the pinned progress
/// bar entirely.
pub struct NonInteractiveWorkflowDisplay {
    mode: OutputMode,
    is_ci: bool,
}

impl NonInteractiveWorkflowDisplay {
    /// Construct a new non-interactive workflow display.
    pub fn new(mode: OutputMode) -> Self {
        Self {
            mode,
            is_ci: crate::shell::is_ci(),
        }
    }

    /// Construct a non-interactive workflow display with an explicit CI
    /// flag (test override).
    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
        Self { mode, is_ci }
    }
}

impl WorkflowDisplay for NonInteractiveWorkflowDisplay {
    fn show_run_header(&mut self, hdr: &RunHeader) {
        if !self.mode.shows_status() {
            return;
        }
        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
        println!(
            "\n⛺ {} v{} · {} workflow · {} {} · env: {}\n",
            hdr.app_name, hdr.version, hdr.workflow, hdr.step_count, step_label, hdr.env_name,
        );
    }

    fn start_progress(&mut self, _total: usize) {}

    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
        if self.is_ci {
            return;
        }
        if !self.mode.shows_status() {
            return;
        }
        let filled = if total > 0 { (current * 16) / total } else { 0 };
        let empty = 16usize.saturating_sub(filled);
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
        println!(
            "  [{}] {}/{} steps · {} elapsed",
            bar,
            current,
            total,
            format_duration(elapsed),
        );
    }

    fn finish_progress(&mut self) {}

    fn show_run_summary(&mut self, summary: &RunSummary) {
        if !self.mode.shows_status() {
            return;
        }

        println!();
        println!("  ┌─ Summary ──────────────────────────");

        for step in &summary.step_results {
            let icon = step.status.icon();
            let duration_str = step.duration.map(format_duration).unwrap_or_default();
            let detail_str = step.detail.as_deref().unwrap_or("");

            let right_side = if !duration_str.is_empty() {
                duration_str
            } else if !detail_str.is_empty() {
                detail_str.to_string()
            } else {
                String::new()
            };

            println!("  │ {} {:<20} {}", icon, step.name, right_side);
        }

        println!("  ├────────────────────────────────────");
        let satisfied_part = if summary.steps_satisfied > 0 {
            format!(" · {} already satisfied", summary.steps_satisfied)
        } else {
            String::new()
        };
        println!(
            "  │ Total: {} · {} run · {} skipped{}",
            format_duration(summary.total_duration),
            summary.steps_run,
            summary.steps_skipped,
            satisfied_part,
        );
        println!("  └────────────────────────────────────");
        // No trailing "Setup complete!" / "Setup failed" line — see the
        // matching note in `TerminalWorkflowDisplay::show_run_summary`.
    }

    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
        Box::new(NonInteractiveStepDisplay::new(self.mode, index, total))
    }

    fn message(&mut self, msg: &str) {
        if self.mode.shows_status() {
            println!("{}", msg);
        }
    }

    fn hint(&mut self, hint: &str) {
        if self.mode.shows_status() {
            println!("  💡 {}", hint);
        }
    }
}

